insert into public.services (slug, title, category, short_description, description, starting_price, sort_order, is_featured, is_published, benefits, features)
values
('shopify-store-development', 'Shopify Store Development', 'Shopify', 'End-to-end conversion-focused Shopify stores built for scale.', 'Complete Shopify storefront architecture, theme configuration, product taxonomy, payment & shipping setup, and launch readiness.', 450, 1, true, true, '["Conversion-focused UX","Mobile-first architecture","Clean Liquid theme structure"]'::jsonb, '["Custom Homepage & Collections","Product Page Optimization","Payment & Shipping Setup","Essential App Integration"]'::jsonb),
('shopify-store-redesign', 'Shopify Store Redesign', 'Shopify', 'Modernize outdated storefronts to elevate brand trust and conversion.', 'Full visual and UX overhaul of existing Shopify stores to improve clarity, mobile usability, and checkout flow.', 380, 2, true, true, '["Higher brand credibility","Modern mobile navigation","Reduced friction in cart"]'::jsonb, '["UX Audit & Wireframing","Theme Upgrade (OS 2.0)","Brand Typography & Palette","Zero Data Loss Migration"]'::jsonb),
('shopify-customization', 'Shopify Customization', 'Shopify', 'Custom Liquid sections, dynamic product options, and tailored UI.', 'Bespoke theme sections, custom metafields, bundle builders, and tailored frontend functionality without heavy third-party apps.', 220, 3, false, true, '["App-free performance","Exact brand match","Clean maintainable code"]'::jsonb, '["Custom Liquid Sections","Metafield Templates","Slide-out Cart Enhancements","Custom Filtering"]'::jsonb),
('shopify-speed-optimization', 'Shopify Speed Optimization', 'Performance', 'Boost Core Web Vitals, cut bloat, and accelerate mobile load times.', 'Deep audit and cleanup of leftover app scripts, render-blocking assets, image compression, and Liquid rendering.', 180, 4, true, true, '["Faster mobile page loads","Improved Core Web Vitals","Lower bounce rates"]'::jsonb, '["App Script Cleanup","Image & Asset Compression","Lazy Loading & Preloading","Theme Code Minification"]'::jsonb),
('shopify-store-management', 'Shopify Store Management', 'Shopify', 'Hands-off daily operations, catalog updates, and store maintenance.', 'Dedicated ongoing store management covering product launches, inventory sync, promotions, and routine health checks.', 300, 5, true, true, '["Consistent store accuracy","Time saved for founders","Proactive issue prevention"]'::jsonb, '["Product & Collection Updates","Promotions & Discount Setup","Order & Inventory Monitoring","Monthly Health Audits"]'::jsonb),
('shopify-bug-fixing', 'Shopify Bug Fixing', 'Shopify', 'Rapid diagnosis and resolution of layout, Liquid, and script issues.', 'Targeted troubleshooting for broken responsive layouts, cart drawer bugs, theme conflicts, and JavaScript errors.', 95, 6, false, true, '["Fast turnaround","Root-cause resolution","Safe theme backups"]'::jsonb, '["Liquid Error Resolution","CSS & Mobile Layout Fixes","JavaScript Conflict Cleanup","Checkout & Cart QA"]'::jsonb),
('product-upload-services', 'Product Upload Services', 'Shopify', 'Accurate bulk product imports, variants, SEO titles, and tagging.', 'Structured product catalog onboarding with clean descriptions, variant mapping, high-res imagery, and SEO metadata.', 120, 7, false, true, '["Clean catalog structure","Consistent variant mapping","Search-ready metadata"]'::jsonb, '["Bulk CSV & Manual Uploads","Variant & SKU Mapping","Image Formatting","Collection & Tag Assignment"]'::jsonb),
('wordpress-development', 'WordPress Development', 'Web', 'Scalable, easy-to-manage WordPress websites for modern businesses.', 'Custom responsive WordPress builds tailored for agencies, corporate teams, service providers, and content platforms.', 350, 8, true, true, '["Easy content editing","Responsive across devices","SEO-ready foundation"]'::jsonb, '["Custom Page Layouts","Contact & Lead Forms","Caching & Security Hardening","Mobile Optimization"]'::jsonb),
('custom-website-development', 'Custom Website Development', 'Web', 'High-performance custom websites engineered with modern web standards.', 'Hand-crafted web applications and corporate sites built for speed, security, and bespoke user experiences.', 550, 9, true, true, '["Zero template bloat","Maximum performance","Scalable architecture"]'::jsonb, '["Modern React / TypeScript or Static Builds","Custom UI Components","API & Database Integration","Full SEO Markup"]'::jsonb),
('landing-page-development', 'Landing Page Development', 'Web', 'High-converting campaign landing pages built for paid traffic.', 'Focused single-page experiences designed to turn ad clicks into qualified leads or product purchases.', 200, 10, false, true, '["Focused conversion funnel","Fast load for ad traffic","Clear CTA hierarchy"]'::jsonb, '["Persuasive Section Flow","Responsive Hero & Proof","Lead Capture Integration","Analytics Pixel Ready"]'::jsonb),
('seo-optimization', 'SEO Optimization', 'Growth', 'Technical SEO, on-page structure, and search visibility improvements.', 'Comprehensive technical and on-page SEO setup including schema markup, metadata, sitemaps, and heading hierarchy.', 250, 11, false, true, '["Cleaner search indexing","Structured data readiness","Better organic discoverability"]'::jsonb, '["Technical SEO Audit","Meta & Schema Markup","Sitemap & Robots Setup","Core Web Vitals Alignment"]'::jsonb),
('conversion-rate-optimization', 'Conversion Rate Optimization', 'Growth', 'Data-informed UX refinements to turn more visitors into buyers.', 'Funnel analysis, product page clarity improvements, trust placement, and checkout friction reduction.', 320, 12, false, true, '["Higher revenue per visitor","Clearer product value","Reduced cart abandonment"]'::jsonb, '["Storefront Funnel Audit","Product Page Hierarchy","Trust & Offer Positioning","A/B Test Recommendations"]'::jsonb),
('meta-ads-management', 'Meta Ads Management', 'Growth', 'Structured Facebook & Instagram ad campaigns for e-commerce growth.', 'Full campaign setup, pixel & CAPI verification, audience structuring, and creative testing coordination.', 400, 13, false, true, '["Structured funnel targeting","Clean pixel tracking","Transparent reporting"]'::jsonb, '["Pixel & Events Verification","Campaign Architecture","Retargeting Setup","Weekly Performance Reports"]'::jsonb),
('google-ads-management', 'Google Ads Management', 'Growth', 'Search and Shopping campaigns built for high-intent buyers.', 'Google Merchant Center alignment, Shopping feed optimization, and Search campaign management.', 400, 14, false, true, '["High-intent traffic capture","Clean product feed setup","Budget efficiency"]'::jsonb, '["Merchant Center & Feed Setup","Search & Shopping Campaigns","Conversion Tracking","Ongoing Bid Optimization"]'::jsonb),
('website-maintenance', 'Website Maintenance', 'Web', 'Ongoing backups, security monitoring, and technical updates.', 'Reliable monthly care plans to keep your Shopify, WordPress, or custom website secure, updated, and fast.', 150, 15, false, true, '["Peace of mind","Regular backups","Priority support"]'::jsonb, '["Scheduled Backups","Uptime & Security Checks","Content & Plugin Updates","Monthly Performance Summary"]'::jsonb)
