insert into public.projects (slug, title, category, short_description, description, cover_image, technologies, project_url, client_type, is_demo, is_featured, is_published)
values
('atelier-noir-shopify-demo', 'Atelier Noir — Luxury Shopify Store (Demo)', 'Shopify', 'Demonstration luxury e-commerce storefront featuring mobile-first product discovery.', 'A demonstration Shopify OS 2.0 storefront showcasing custom hero storytelling, sticky add-to-cart, clean collection filtering, and streamlined mobile checkout.', 'images/project-shopify.jpg', '["Shopify OS 2.0","Liquid","JavaScript","CSS3"]'::jsonb, 'https://realkhizar37-ops.github.io/my-first-project/', 'Demo Showcase', true, true, true),
('core-web-vitals-speed-demo', 'Storefront Speed Optimization Audit (Demo)', 'Speed', 'Demonstration performance engineering workflow targeting 90+ Core Web Vitals.', 'A demonstration speed optimization case showing unused script removal, asset preloading, image compression, and layout shift elimination.', 'images/project-speed.svg', '["Core Web Vitals","Liquid Optimization","Asset Preloading"]'::jsonb, 'https://realkhizar37-ops.github.io/my-first-project/', 'Demo Showcase', true, true, true),
('corporate-web-platform-demo', 'B2B Digital Agency Web Platform (Demo)', 'Web', 'Demonstration responsive WordPress and custom web architecture for service brands.', 'A demonstration multi-page service website built with semantic HTML, modern responsive grids, SEO metadata, and direct WhatsApp lead capture.', 'images/project-web.jpg', '["WordPress","React","TypeScript","SEO"]'::jsonb, 'https://realkhizar37-ops.github.io/my-first-project/', 'Demo Showcase', true, true, true)
insert into public.faqs (question, answer, category, sort_order, is_published)
values
('How long does a typical Shopify or website project take?', 'Starter projects typically take 5–7 business days, while Growth and Professional builds take 1–3 weeks depending on custom features and catalog size.', 'Timeline', 1, true),
('Do you provide ongoing Shopify store management after launch?', 'Yes. We offer dedicated Shopify Store Full Management covering product uploads, promotions, inventory updates, and ongoing maintenance.', 'Services', 2, true),
('Will speed optimization affect my current store design or apps?', 'No. We always back up your theme before making changes and carefully optimize assets and unused leftover scripts without breaking active functionality.', 'Performance', 3, true),
('Are the prices shown in the Cost Calculator final?', 'No — the Cost Calculator provides an instant project estimate based on your selections. Final pricing is confirmed after reviewing your exact requirements.', 'Pricing', 4, true);
